CREATE TABLE IF NOT EXISTS usuarios(id INTEGER PRIMARY KEY AUTOINCREMENT,nombre TEXT NOT NULL,correo TEXT NOT NULL UNIQUE,clave_hash TEXT NOT NULL,rol TEXT NOT NULL DEFAULT 'vendedor',activo INTEGER NOT NULL DEFAULT 1,bloqueado_hasta TEXT NULL,creado_en TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS intentos_acceso(id INTEGER PRIMARY KEY AUTOINCREMENT,correo TEXT NOT NULL,exito INTEGER NOT NULL,fecha TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,ip TEXT);
CREATE TABLE IF NOT EXISTS categorias(id INTEGER PRIMARY KEY AUTOINCREMENT,nombre TEXT NOT NULL UNIQUE,descripcion TEXT,activo INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS productos(id INTEGER PRIMARY KEY AUTOINCREMENT,nombre TEXT NOT NULL,categoria_id INTEGER NOT NULL,precio REAL NOT NULL,stock INTEGER NOT NULL DEFAULT 0,stock_minimo INTEGER NOT NULL DEFAULT 5,activo INTEGER NOT NULL DEFAULT 1,creado_en TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(categoria_id) REFERENCES categorias(id));
CREATE TABLE IF NOT EXISTS clientes(id INTEGER PRIMARY KEY AUTOINCREMENT,nombre TEXT NOT NULL,documento TEXT NOT NULL UNIQUE,correo TEXT,telefono TEXT,activo INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS pedidos(id INTEGER PRIMARY KEY AUTOINCREMENT,cliente_id INTEGER NOT NULL,fecha TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,total REAL NOT NULL DEFAULT 0,estado TEXT NOT NULL DEFAULT 'confirmado',FOREIGN KEY(cliente_id) REFERENCES clientes(id));
CREATE TABLE IF NOT EXISTS detalle_pedido(id INTEGER PRIMARY KEY AUTOINCREMENT,pedido_id INTEGER NOT NULL,producto_id INTEGER NOT NULL,cantidad INTEGER NOT NULL,precio_unitario REAL NOT NULL,FOREIGN KEY(pedido_id) REFERENCES pedidos(id) ON DELETE CASCADE,FOREIGN KEY(producto_id) REFERENCES productos(id));
